import{_ as a,o as t,c as r,ae as n}from"./chunks/framework.Bwt6MOeu.js";const u=JSON.parse('{"title":"23-Topic Canon","description":"","frontmatter":{},"headers":[],"relativePath":"guide/twenty-three-topic-canon.md","filePath":"guide/twenty-three-topic-canon.md"}'),i={name:"guide/twenty-three-topic-canon.md"};function o(s,e,l,h,c,d){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_23-topic-canon" tabindex="-1">23-Topic Canon <a class="header-anchor" href="#_23-topic-canon" aria-label="Permalink to &quot;23-Topic Canon&quot;">​</a></h1><p>The 23-Topic Canon is the navigational spine for the broader SocioProphet system.</p><p>It is public because institutions need to understand the conceptual surface area of the platform. It is summarized here in a public-safe way.</p><h2 id="_1-why-a-canon-exists" tabindex="-1">1. Why a canon exists <a class="header-anchor" href="#_1-why-a-canon-exists" aria-label="Permalink to &quot;1. Why a canon exists&quot;">​</a></h2><p>The canon exists so the system can remain:</p><ul><li>addressable</li><li>teachable</li><li>comparable over time</li><li>mappable across product surfaces</li><li>disciplined during growth</li></ul><h2 id="_2-the-three-groupings" tabindex="-1">2. The three groupings <a class="header-anchor" href="#_2-the-three-groupings" aria-label="Permalink to &quot;2. The three groupings&quot;">​</a></h2><h3 id="heaven-1–11" tabindex="-1">Heaven (1–11) <a class="header-anchor" href="#heaven-1–11" aria-label="Permalink to &quot;Heaven (1–11)&quot;">​</a></h3><p>These topics describe the lower and more infrastructural layers: hardware, boot, kernel, drivers, runtimes, IPC, network, identity, storage, and telemetry.</p><h3 id="earth-12–22" tabindex="-1">Earth (12–22) <a class="header-anchor" href="#earth-12–22" aria-label="Permalink to &quot;Earth (12–22)&quot;">​</a></h3><p>These topics describe user, application, content, cloud, supply-chain, and operational surfaces such as browsers, documents, fonts, email, cloud APIs, administration, and tooling.</p><h3 id="mesh-23" tabindex="-1">Mesh (23) <a class="header-anchor" href="#mesh-23" aria-label="Permalink to &quot;Mesh (23)&quot;">​</a></h3><p>This topic is the control and trust mesh that governs policy, ownership, risk, provenance, and chain-of-custody across the broader system.</p><h2 id="_3-what-the-canon-is-for" tabindex="-1">3. What the canon is for <a class="header-anchor" href="#_3-what-the-canon-is-for" aria-label="Permalink to &quot;3. What the canon is for&quot;">​</a></h2><p>The canon helps organize:</p><ul><li>curriculum</li><li>operational surfaces</li><li>evidence and provenance</li><li>graph semantics</li><li>topic-addressable documentation</li><li>institutional deployment conversations</li></ul><h2 id="_4-public-safe-boundary" tabindex="-1">4. Public-safe boundary <a class="header-anchor" href="#_4-public-safe-boundary" aria-label="Permalink to &quot;4. Public-safe boundary&quot;">​</a></h2><p>We publish the canon as an organizing framework.</p><p>We do not publish every restricted implementation detail, simulation recipe, or threshold associated with every topic.</p><h2 id="_5-related-references" tabindex="-1">5. Related references <a class="header-anchor" href="#_5-related-references" aria-label="Permalink to &quot;5. Related references&quot;">​</a></h2><ul><li><a href="./operating-modes-learning-and-defense">Operating Modes: Learning and Defense</a></li><li><a href="./boundary-centric-cyber-hypergraph">Boundary-Centric Cyber Hypergraph</a></li><li><a href="./agent-corps-and-operational-roles">Agent Corps and Operational Roles</a></li></ul>',21)])])}const f=a(i,[["render",o]]);export{u as __pageData,f as default};
